function buildSwampBird(rnd, color) {
  const g = new THREE.Group();
  g.name = "swamp-bird";
  // Same approved anatomy: colour belongs to real head, breast and feather pieces.
  const head=0xdd93ab,breast=0xf1d59a,wingColor=0x80cec1,tailColor=0x65b4ae,featherLight=0xb8f3d5;
  const pieces = [
    coralEllipsoid([0,0,0],[.24,.22,.51],breast),
    coralEllipsoid([0,.14,.43],[.21,.2,.25],head),
    coralEllipsoid([0,.11,.68],[.065,.07,.21],0x8a7782),
    coralEllipsoid([-.095,.01,-.6],[.085,.04,.3],tailColor,[0,-.14,0]),
    coralEllipsoid([.095,.01,-.6],[.085,.04,.3],tailColor,[0,.14,0]),
    ...[-1,1].map(side=>coralEllipsoid([side*.183,.19,.48],[.028,.033,.033],CORAL_ACTOR_INK))
  ];
  const body=coralFineActorBatch(pieces);body.name='swamp-bird-anatomy';g.add(body);
  for(const side of [-1,1]) {
    const wing=coralFineActorBatch([
      coralEllipsoid([side*.44,0,-.03],[.62,.055,.29],wingColor,[0,side*.25,0]),
      coralEllipsoid([side*.85,-.015,-.23],[.42,.035,.12],featherLight,[0,side*.45,0])
    ]);
    wing.position.set(side*.17,.08,0);wing.rotation.z=side*.5;
    wing.userData.side=side;wing.name='swamp-bird-wing';g.add(wing);
    g.userData[`wing${side>0?'R':'L'}`]=wing;
  }
  // The previous central glow sat inside the opaque bird. Put the light in a
  // transparent-centred outer feather aureole instead: one shared texture and
  // the same single sprite, no point lights or per-frame resource allocation.
  body.material.toneMapped=false;
  for(const wing of [g.userData.wingL,g.userData.wingR])wing.material.toneMapped=false;
  if(!buildSwampBird.aureoleTexture){
    const size=64,data=new Uint8Array(size*size*4);
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const radius=Math.hypot((x+.5-size/2)/(size/2),(y+.5-size/2)/(size/2));
      const inner=THREE.MathUtils.smoothstep(radius,.32,.60),outer=1-THREE.MathUtils.smoothstep(radius,.62,1);
      const i=(y*size+x)*4;data[i]=data[i+1]=data[i+2]=255;data[i+3]=Math.round(255*.72*inner*outer);
    }
    const texture=new THREE.DataTexture(data,size,size,THREE.RGBAFormat);
    texture.magFilter=texture.minFilter=THREE.LinearFilter;texture.needsUpdate=true;
    buildSwampBird.aureoleTexture=texture;
  }
  const halo = glowSprite(0x91efce, 4.1, 0.38, 'signal');
  halo.scale.set(4.1,1.75,1);halo.position.set(0,.08,-.08);
  halo.material.map=buildSwampBird.aureoleTexture;
  halo.material.blending=THREE.NormalBlending;halo.material.toneMapped=false;
  g.add(halo);g.userData.halo=halo;
  g.userData.orbitR = 15 + rnd() * 11;
  g.userData.orbitY = 44 + rnd() * 7;
  g.userData.dart = 2.5 + rnd() * 3.5;
  g.userData.speed = 0.22 + rnd() * 0.18;
  g.userData.phase = rnd() * Math.PI * 2;
  g.userData.coralActorVersion=1;
  return g;
}

